<script setup lang="ts">
import { onMounted, onUnmounted, reactive, ref } from 'vue'
import type { ExportJob, Management, Media, Recording, SearchResult } from './api'
import { stateName } from './api'
import { useConsole } from './context'
const { api, run, notify } = useConsole()
const filters = reactive({search:'',from:'',to:'',station:''}), items = ref<Recording[]>([]), total = ref(0), page = ref(1)
const jobs = ref<ExportJob[]>([]), selected = ref<Recording | null>(null), playerURL = ref(''), downloadURL = ref(''), title = ref(''), exportMode = ref(false)
const start = ref(0), end = ref(0), leases: Media[] = [], loading = ref(false)
async function load() { loading.value = true; try { const result = await api.request<SearchResult>('/v1/library?' + new URLSearchParams({...filters,page:String(page.value)})); items.value = result.items; total.value = result.total } finally { loading.value = false } }
async function refreshJobs() { jobs.value = (await api.request<Management>('/v1/management')).exports }
function releaseAll() { for (const lease of leases.splice(0)) void api.release(lease).catch(() => {}); playerURL.value=''; downloadURL.value='' }
async function media(body: {record_id?:string; export_id?:string}) { const lease = await api.media(body); leases.push(lease); return lease.url }
async function play(record: Recording) { releaseAll(); selected.value=record; title.value=record.barcode; exportMode.value=false; start.value=0;end.value=record.duration;playerURL.value=await media({record_id:record.id});downloadURL.value=(await media({record_id:record.id}))+'?download=1' }
async function playExport(job: ExportJob) { releaseAll(); exportMode.value=true;title.value='兼容回放 / 剪辑';playerURL.value=await media({export_id:job.id}) }
async function download(job: ExportJob) { const a=document.createElement('a');a.href=(await media({export_id:job.id}))+'?download=1';a.download='';a.click() }
async function clip() { if(!selected.value)return;await api.request('/v1/exports',{record_id:selected.value.id,start:start.value,end:end.value});notify('导出任务已排队，原始录像保留。');await refreshJobs() }
onMounted(() => { void run(async()=>{await load();await refreshJobs()}) })
const timer = setInterval(()=>void run(refreshJobs),5000)
onUnmounted(()=>{clearInterval(timer);releaseAll()})
</script>
<template><section class="card"><div class="section-title"><div><h2>查找打包录像</h2><p class="muted">通过单号定位录像，保留每一次打包记录。</p></div><span class="count-badge">{{ total }} 条记录</span></div><form class="filter-grid" @submit.prevent="page=1;run(load)"><label>快递单号<input id="search" v-model="filters.search" placeholder="输入单号关键词"></label><label>开始日期<input id="from" v-model="filters.from" type="date"></label><label>结束日期<input id="to" v-model="filters.to" type="date"></label><label>工位<input v-model="filters.station" placeholder="工位 ID，可选"></label><button class="primary" :disabled="loading">查询录像</button></form><div class="table-scroll"><table><thead><tr><th>快递单号</th><th>工位 / 时间</th><th>时长</th><th>录像状态</th><th>备份状态</th><th></th></tr></thead><tbody><tr v-for="record in items" :key="record.id"><td class="strong">{{ record.barcode }}</td><td>{{ record.station_name }}<small>{{ record.start_time }}</small></td><td>{{ record.duration.toFixed(1) }} 秒</td><td><span class="badge" :class="record.capture.interrupted?'amber':'green'">{{ record.capture.interrupted?'故障片段':'已归档' }}</span></td><td>{{ stateName[record.upload_state] || record.upload_state }}</td><td><button class="text-button" @click="run(()=>play(record))">回放 →</button></td></tr><tr v-if="!items.length"><td colspan="6"><div class="empty"><span>▤</span><h3>{{ loading?'正在加载…':'暂无匹配的录像' }}</h3><p>录像保存后会显示在这里，也可以调整查询条件。</p></div></td></tr></tbody></table></div><div class="pagination"><span class="muted">共 {{ total }} 条 · 第 {{ page }} 页</span><div class="row"><button :disabled="page===1||loading" @click="page--;run(load)">上一页</button><button :disabled="page*50>=total||loading" @click="page++;run(load)">下一页</button></div></div></section>
<section v-if="playerURL" class="card"><div class="section-title"><h2>{{ title }}</h2><button @click="releaseAll">关闭回放</button></div><video :src="playerURL" controls playsinline></video><p class="muted">浏览器不支持原始格式时，可生成 H.264 MP4 兼容回放文件。</p><form v-if="!exportMode" class="row" @submit.prevent="run(clip)"><label>开始秒<input v-model.number="start" type="number" min="0" step="0.1" required></label><label>结束秒<input v-model.number="end" type="number" min="0" step="0.1" required></label><button class="primary">生成兼容回放 / 剪辑</button><a :href="downloadURL" download>下载原片</a></form></section>
<section class="card"><div class="section-title"><div><h2>导出任务</h2><p class="muted">独立生成 MP4 文件，原片保持完整。</p></div><button @click="run(refreshJobs)">刷新</button></div><div v-if="!jobs.length" class="empty compact">还没有导出任务。选择录像后可以生成兼容回放或剪辑。</div><div v-for="job in jobs" :key="job.id" class="job-row"><div><span class="badge" :class="job.state==='error'?'amber':job.state==='ready'?'green':''">{{ stateName[job.state]||job.state }}</span> <span>{{ job.start }} ～ {{ job.end }} 秒</span><p v-if="job.error" class="error-text">{{ job.error }}</p></div><div v-if="job.state==='ready'" class="row"><button @click="run(()=>playExport(job))">播放</button><button @click="run(()=>download(job))">下载 MP4</button></div></div></section></template>
